# Defaults to eval/table.txt; prints to stdout when no output path is given.
# Required LaTeX packages: longtable, booktabs, multirow, xcolor (table option), arydshln.

import sys

in_path = sys.argv[1] if len(sys.argv) > 1 else "eval/table.txt"
out_path = sys.argv[2] if len(sys.argv) > 2 else None
raw = open(in_path).read()

DATASETS = ["Wine", "Protein", "Parkinson", "Keggu", "Road"]
DIMS = {"Wine": 11, "Protein": 9, "Parkinson": 19, "Keggu": 24, "Road": 2}

records = []
cur = None
for line in raw.splitlines():
    line = line.strip()
    if not line:
        continue
    if not line.startswith(tuple(DATASETS)):
        toks = line.split()
        sv = "SV" in toks
        opt = next((t for t in toks if t in ("Adam", "LBFGS")), "Adam")
        gp = " ".join(t for t in toks if t not in ("Adam", "LBFGS", "SV"))
        cur = (gp, opt, sv)
    else:
        parts = [x.strip() for x in line.split(",")]
        records.append((cur, parts[0], tuple(float(x) for x in parts[1:])))

GPSEQ = ["Exact", "ExactCG", "SVGP random", "SVGP kmeans", "CAGP"]
OPTS = {"Exact": ["Adam", "LBFGS"], "ExactCG": ["Adam", "LBFGS"],
        "SVGP random": ["Adam"], "SVGP kmeans": ["Adam"], "CAGP": ["Adam"]}


def label(gp):
    if gp.startswith("SVGP"):
        return "SVGP (" + ("random init." if "random" in gp else "k-means init.") + ")"
    return {"Exact": "ExactGP", "ExactCG": "ExactGP-CG", "CAGP": "CAGP"}[gp]


by = {}
for (gp, opt, sv), ds, vals in records:
    by.setdefault(ds, []).append((gp, opt, sv, vals))


def rows_for(ds):
    out = []
    for gp in GPSEQ:
        for opt in OPTS[gp]:
            rs = [r for r in by[ds] if r[0] == gp and r[1] == opt]
            rs.sort(key=lambda r: not r[2])
            out.extend(rs)
    return out


COLORS = ["gold", "silver", "bronze"]
FMTS = ["{:.3f}", "{:.4f}", "{:.3f}", "{:.4f}", "{:.1f}"]


def color_assign(vals):
    order = sorted(range(len(vals)), key=lambda i: vals[i])
    cols = [None] * len(vals)
    for rank, idx in enumerate(order[:3]):
        cols[idx] = COLORS[rank]
    return cols


body = []
for di, ds in enumerate(DATASETS):
    rows = rows_for(ds)
    colors = [color_assign([r[3][1 + m] for r in rows]) for m in range(5)]
    for ri, (gp, opt, sv, vals) in enumerate(rows):
        ln, rm, rs, nm, ns, rt = vals
        metric_vals = [rm, rs, nm, ns, rt]
        cells = []
        if ri == 0:
            cells.append(f"\\multirow{{{len(rows)}}}{{*}}{{{ds}}}")
            cells.append(f"\\multirow{{{len(rows)}}}{{*}}{{{DIMS[ds]}}}")
        else:
            cells += ["", ""]
        if ri == 0 or gp != rows[ri - 1][0]:
            span = sum(1 for r in rows if r[0] == gp)
            cells.append(f"\\multirow{{{span}}}{{*}}{{{label(gp)}}}")
        else:
            cells.append("")
        cells.append(opt)
        cells.append("Yes" if sv else "No")
        for m in range(5):
            s = FMTS[m].format(metric_vals[m])
            if colors[m][ri]:
                s = f"\\cellcolor{{{colors[m][ri]}}}{s}"
            cells.append(s)
        term = "\\\\*" if ri < len(rows) - 1 else "\\\\"
        line = " & ".join(cells) + " " + term
        if ri < len(rows) - 1 and rows[ri + 1][0] != gp:
            line += " \\cdashline{3-10}"
        body.append(line)
    if di < len(DATASETS) - 1:
        body.append("\\midrule")

head = [
    "\\toprule",
    "\\multirow{2}{*}{Dataset} & \\multirow{2}{*}{$d$} & \\multirow{2}{*}{GP Method} & \\multirow{2}{*}{Optimizer} & \\multirow{2}{*}{OS trained} & \\multicolumn{2}{c}{RMSE} & \\multicolumn{2}{c}{NLL} & \\multirow{2}{*}{Time (s)}\\\\",
    "\\cmidrule(lr){6-7}\\cmidrule(lr){8-9}",
    " & & & & & mean & std & mean & std & \\\\",
    "\\midrule",
]

out = []
out.append("{\\footnotesize")
out.append("\\setlength{\\tabcolsep}{3.5pt}")
out.append("\\begin{longtable}{@{}llcccccccc@{}}")
out.append("\\caption{Mean test-set metrics over seeds for each configuration and dataset. RMSE/NLL are reported as mean and standard deviation; runtime in seconds. Best three values per dataset and metric are highlighted in gold, silver and bronze.}")
out.append("\\label{tab:gp_results}\\\\")
out.extend(head)
out.append("\\endfirsthead")
out.extend(head)
out.append("\\endhead")
out.append("\\midrule")
out.append("\\multicolumn{10}{r}{\\footnotesize\\emph{Continued on next page}}\\\\")
out.append("\\endfoot")
out.append("\\bottomrule")
out.append("\\endlastfoot")
out.extend(body)
out.append("\\end{longtable}")
out.append("}")

text = "\n".join(out)
if out_path:
    with open(out_path, "w") as f:
        f.write(text + "\n")
else:
    print(text)
